class ReviewManager{constructor(){this.reviews=[];this.currentFilter='all';}initialize(){this.setupExpandCollapse();this.setupHelpfulVotes();this.setupFiltering();}setupExpandCollapse(){const reviewTexts=document.querySelectorAll('[data-review-text]');reviewTexts.forEach(reviewText=>{const fullText=reviewText.dataset.reviewText;const maxLength=parseInt(reviewText.dataset.maxLength||150,10);if(fullText.length>maxLength){const truncatedText=fullText.substring(0,maxLength)+'...';const textSpan=document.createElement('span');textSpan.className='review-text-content';textSpan.textContent=truncatedText;const toggleButton=document.createElement('button');toggleButton.className='review-toggle-btn';toggleButton.textContent='Show more';toggleButton.setAttribute('aria-expanded','false');reviewText.innerHTML='';reviewText.appendChild(textSpan);reviewText.appendChild(toggleButton);let isExpanded=false;toggleButton.addEventListener('click',()=>{isExpanded=!isExpanded;if(isExpanded){textSpan.textContent=fullText;toggleButton.textContent='Show less';toggleButton.setAttribute('aria-expanded','true');}else{textSpan.textContent=truncatedText;toggleButton.textContent='Show more';toggleButton.setAttribute('aria-expanded','false');}});}else{reviewText.textContent=fullText;}});}setupHelpfulVotes(){const voteButtons=document.querySelectorAll('[data-review-vote]');voteButtons.forEach(button=>{const reviewId=button.dataset.reviewId;const voteType=button.dataset.reviewVote;button.addEventListener('click',()=>{this.handleVote(reviewId,voteType,button);});});}handleVote(reviewId,voteType,button){const storageKey=`review-vote-${reviewId}`;const existingVote=localStorage.getItem(storageKey);if(existingVote){button.classList.add('voted');this.showVoteMessage(button,'You already voted on this review');return;}localStorage.setItem(storageKey,voteType);button.classList.add('voted');const countElement=button.querySelector('[data-vote-count]');if(countElement){const currentCount=parseInt(countElement.textContent,10);countElement.textContent=currentCount+1;}this.showVoteMessage(button,'Thank you for your feedback!');}showVoteMessage(button,message){const messageElement=document.createElement('span');messageElement.className='vote-message';messageElement.textContent=message;button.parentElement.appendChild(messageElement);setTimeout(()=>{messageElement.remove();},2000);}setupFiltering(){const filterButtons=document.querySelectorAll('[data-review-filter]');filterButtons.forEach(button=>{button.addEventListener('click',()=>{const filterValue=button.dataset.reviewFilter;this.applyFilter(filterValue);filterButtons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');});});}applyFilter(filterValue){this.currentFilter=filterValue;const reviewCards=document.querySelectorAll('[data-review-card]');reviewCards.forEach(card=>{const rating=parseInt(card.dataset.rating,10);const verified=card.dataset.verified==='true';let shouldShow=true;switch(filterValue){case 'all': shouldShow=true;break;case 'verified': shouldShow=verified;break;case '5-star': shouldShow=rating===5;break;case '4-star': shouldShow=rating===4;break;case '3-star': shouldShow=rating===3;break;case '2-star': shouldShow=rating===2;break;case '1-star': shouldShow=rating===1;break;default: shouldShow=true;}if(shouldShow){card.style.display='';card.classList.remove('filtered-out');}else{card.style.display='none';card.classList.add('filtered-out');}});this.updateVisibleCount();}updateVisibleCount(){const visibleReviews=document.querySelectorAll('[data-review-card]:not(.filtered-out)');const countElement=document.querySelector('[data-visible-review-count]');if(countElement){countElement.textContent=visibleReviews.length;}}loadMore(count=3){const hiddenReviews=document.querySelectorAll('[data-review-card].hidden');const reviewsToShow=Array.from(hiddenReviews).slice(0,count);reviewsToShow.forEach(review=>{review.classList.remove('hidden');});if(hiddenReviews.length<=count){const loadMoreButton=document.querySelector('[data-load-more-reviews]');if(loadMoreButton){loadMoreButton.style.display='none';}}}}class ReviewCarousel{constructor(carouselElement){this.carousel=carouselElement;this.track=this.carousel.querySelector('.carousel-track');this.cards=Array.from(this.track.querySelectorAll('.review-card-carousel'));this.prevButton=this.carousel.querySelector('.carousel-prev');this.nextButton=this.carousel.querySelector('.carousel-next');this.indicators=Array.from(document.querySelectorAll('.carousel-indicators .indicator'));this.currentIndex=0;this.autoScrollInterval=null;this.autoScrollDelay=5000;this.initialize();}initialize(){if(!this.track||this.cards.length===0){return;}this.setupNavigation();this.setupIndicators();this.setupAutoScroll();this.updateCarousel();}setupNavigation(){if(this.prevButton){this.prevButton.addEventListener('click',()=>{this.previous();});}if(this.nextButton){this.nextButton.addEventListener('click',()=>{this.next();});}}setupIndicators(){this.indicators.forEach((indicator,index)=>{indicator.addEventListener('click',()=>{this.goTo(index);});});}setupAutoScroll(){this.startAutoScroll();this.carousel.addEventListener('mouseenter',()=>{this.stopAutoScroll();});this.carousel.addEventListener('mouseleave',()=>{this.startAutoScroll();});if(this.prevButton){this.prevButton.addEventListener('click',()=>{this.stopAutoScroll();this.startAutoScroll();});}if(this.nextButton){this.nextButton.addEventListener('click',()=>{this.stopAutoScroll();this.startAutoScroll();});}}startAutoScroll(){this.stopAutoScroll();this.autoScrollInterval=setInterval(()=>{this.next();},this.autoScrollDelay);}stopAutoScroll(){if(this.autoScrollInterval){clearInterval(this.autoScrollInterval);this.autoScrollInterval=null;}}next(){if(this.currentIndex<this.cards.length-1){this.currentIndex++;}else{this.currentIndex=0;}this.updateCarousel();}previous(){if(this.currentIndex>0){this.currentIndex--;}else{this.currentIndex=this.cards.length-1;}this.updateCarousel();}goTo(index){if(index>=0&&index<this.cards.length){this.currentIndex=index;this.updateCarousel();this.stopAutoScroll();this.startAutoScroll();}}updateCarousel(){const cardWidth=this.cards[0].offsetWidth;const gap=parseInt(getComputedStyle(this.track).gap)||0;const offset=-(this.currentIndex*(cardWidth+gap));this.track.style.transform=`translateX(${offset}px)`;this.updateNavigationButtons();this.updateIndicators();this.updateCountIndicator();}updateNavigationButtons(){}updateIndicators(){this.indicators.forEach((indicator,index)=>{if(index===this.currentIndex){indicator.classList.add('active');}else{indicator.classList.remove('active');}});}updateCountIndicator(){const countElement=document.querySelector('.summary-count');if(countElement){const currentNum=this.currentIndex+1;const total=this.cards.length;const baseText=countElement.textContent.replace(/\d+/,'');countElement.textContent=`Showing ${currentNum}of ${total}reviews`;}}getCurrentIndex(){return this.currentIndex;}getTotalReviews(){return this.cards.length;}}function initializeReviews(){const reviewManager=new ReviewManager();reviewManager.initialize();const loadMoreButton=document.querySelector('[data-load-more-reviews]');if(loadMoreButton){loadMoreButton.addEventListener('click',()=>{reviewManager.loadMore();});}const carouselElement=document.querySelector('[data-review-carousel]');if(carouselElement){const reviewCarousel=new ReviewCarousel(carouselElement);window.reviewCarousel=reviewCarousel;}window.reviewManager=reviewManager;}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initializeReviews);}else{initializeReviews();}function initializeReviewFilters(){const filterButtons=document.querySelectorAll('.filter-btn');const reviewCards=document.querySelectorAll('.review-card');if(filterButtons.length===0||reviewCards.length===0)return;filterButtons.forEach(button=>{button.addEventListener('click',()=>{filterButtons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');const filter=button.dataset.filter;reviewCards.forEach(card=>{const rating=card.querySelector('.review-rating').children.length;const isVerified=card.querySelector('.verified-badge')!==null;const isFeatured=card.classList.contains('featured');let shouldShow=false;switch(filter){case 'all': shouldShow=true;break;case '5': shouldShow=rating===5||isFeatured;break;case '4': shouldShow=rating===4;break;case 'verified': shouldShow=isVerified||isFeatured;break;default: shouldShow=true;}if(shouldShow){card.style.display='flex';card.style.animation='fadeInUp 0.4s ease-out';}else{card.style.display='none';}});});});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initializeReviewFilters);}else{initializeReviewFilters();}